#include <assert.h>
#include <stdio.h>
#include "command_replay.h"
using namespace competition_shadow;
static void add(CommandReplayWindow& w,uint32_t id,uint32_t seq,uint8_t type,uint32_t fp=1){w.store(id,seq,type,1,24,fp,0,0,100);}
int main(){CommandReplayWindow w;const ReplayEntry* e=nullptr;assert(w.inspect(100,100,68,1,24,1,e)==ReplayDecision::New);add(w,100,100,68);assert(w.inspect(100,100,68,1,24,1,e)==ReplayDecision::Duplicate&&e&&e->appliedUs==100);assert(w.inspect(100,101,68,1,24,1,e)==ReplayDecision::ProtocolConflict);assert(w.inspect(101,100,68,1,24,1,e)==ReplayDecision::ProtocolConflict);assert(w.inspect(100,100,69,1,24,1,e)==ReplayDecision::ProtocolConflict);assert(w.inspect(100,100,68,1,24,2,e)==ReplayDecision::ProtocolConflict);assert(w.inspect(99,99,68,1,24,1,e)==ReplayDecision::Stale);for(uint32_t i=101;i<166;++i){assert(w.inspect(i,i,68,1,24,1,e)==ReplayDecision::New);add(w,i,i,68);}assert(w.inspect(1,1,68,1,24,1,e)==ReplayDecision::Stale);CommandReplayWindow wrap;add(wrap,1,0xfffffffeu,68);assert(wrap.inspect(2,0xffffffffu,68,1,24,1,e)==ReplayDecision::New);add(wrap,2,0xffffffffu,68);assert(wrap.inspect(3,0u,68,1,24,1,e)==ReplayDecision::New);add(wrap,3,0u,68);assert(wrap.inspect(4,1u,68,1,24,1,e)==ReplayDecision::New);assert(wrap.inspect(5,0x80000000u,68,1,24,1,e)==ReplayDecision::Stale);assert(w.duplicateCount()==1&&w.conflictCount()==4&&w.staleCount()>=2);puts("COMMAND_REPLAY_HOST_PASS capacity=64 duplicate=ok conflict=ok stale=ok wrap=ok");}
